@return The generated RSA private key in PEM format, or an empty string if an error occurred.
*/
std::string create_private_key() {
    const int key_length = 2048; // Default key length, can be adjusted
    // The command should output the key to stdout, which popen captures.
    // Redirecting stderr to /dev/null as per the prompt.
    std::string command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:" + std::to_string(key_length) + " 2>/dev/null";

    // Use popen to execute the command and capture its stdout.
    // The second argument "r" opens the pipe for reading.
    std::array<char, 4096> buffer; // Increased buffer size for potentially larger keys
    std::string result;
    std::unique_ptr<FILE, decltype(&pclose)> pipe(popen(command.c_str(), "r"), pclose);

    if (!pipe) {
        // Error opening pipe or command execution failed at the popen level.
        return "";
    }

    // Read the output from the pipe into the buffer and append to the result string.
    // This loop correctly handles multi-line output.
    while (fgets(buffer.data(), buffer.size(), pipe.get()) != nullptr) {
        result += buffer.data();
    }

    // A valid PEM key should not be empty and should start with "-----BEGIN PRIVATE KEY-----"
    // or similar depending on the exact openssl version and output format.
    // A simple check for non-emptiness is a basic indicator, but a more robust check
    // would involve parsing the PEM structure. For this problem, we assume a non-empty
    // string is a successful generation.
    if (result.empty()) {
        return "";
    }

    return result;
}
